import json
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message

DEFAULT_STAMINA = {"current": 100, "max": 100}

class GetStaminaComponent(Component):
    display_name = "Get Stamina Component"
    description = "前段から受け取ったスタミナ値を整形して返す"
    icon = "battery"

    inputs = [
        MessageTextInput(
            name="stamina_data",
            display_name="Stamina Data",
            info="前段(Recover Stamina Component)からのJSON文字列",
        ),
    ]

    outputs = [
        Output(display_name="Message", name="message", method="get_stamina"),
    ]

    def get_stamina(self) -> Message:
        try:
            data = json.loads(self.stamina_data)
            current = data["current"]
            max_val = data["max"]
        except (json.JSONDecodeError, KeyError, TypeError):
            # 前段未接続・空文字・不正な値の場合のデフォルト
            current = DEFAULT_STAMINA["current"]
            max_val = DEFAULT_STAMINA["max"]

        result = {"stamina": {"current": current, "max": max_val}}
        return Message(text=json.dumps(result, ensure_ascii=False))
